from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, divisor: int) -> int:
    """Count nonzero-digit suffixes with a given sum and product requirement."""
    if length == 0:
        return int(digit_sum == 0 and divisor == 1)
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    return sum(
        _suffix_count(length - 1, digit_sum - digit, divisor // gcd(divisor, digit))
        for digit in range(max(1, digit_sum - 9 * (length - 1)),
                           min(9, digit_sum - (length - 1)) + 1)
    )


def _smooth(value: int) -> bool:
    for prime in (2, 3, 5, 7):
        while value % prime == 0:
            value //= prime
    return value == 1


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    size = len(digits)

    # Every positive number containing a zero has zero digit product.
    nonzero = sum(9 ** length for length in range(1, size))
    for index, digit in enumerate(digits):
        if digit == 0:
            break
        nonzero += (digit - 1) * 9 ** (size - index - 1)
    else:
        nonzero += 1

    beautiful_nonzero = 0
    for target_sum in range(1, 9 * size + 1):
        # A nonzero digit product has no prime factors greater than seven.
        if not _smooth(target_sum):
            continue
        for length in range(1, size):
            beautiful_nonzero += _suffix_count(length, target_sum, target_sum)

        remaining_sum = target_sum
        divisor = target_sum
        for index, digit in enumerate(digits):
            for smaller in range(1, digit):
                beautiful_nonzero += _suffix_count(
                    size - index - 1,
                    remaining_sum - smaller,
                    divisor // gcd(divisor, smaller),
                )
            if digit == 0:
                break
            remaining_sum -= digit
            divisor //= gcd(divisor, digit)
        else:
            beautiful_nonzero += int(remaining_sum == 0 and divisor == 1)

    return bound - nonzero + beautiful_nonzero


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A positive integer is beautiful if the product of its digits is divisible
    by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive).
        r: The upper bound of the range (inclusive).

    Returns:
        The count of beautiful numbers in the range [l, r].

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

