def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count replacements with different digits in edge-sharing cells.

    The answer is returned modulo 998244353. The grid consists of '1',
    '2', '3', and '?', and has at most 200 cells.
    """
    mod = 998244353
    # Sweep along the longer dimension so the frontier has at most 14 cells.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Two bits per frontier cell; zero denotes an unvisited cell.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            clear = ~(3 << shift)
            cell = grid[r][c]
            choices = (1, 2, 3) if cell == '?' else (int(cell),)
            next_dp = {}
            for state, ways in dp.items():
                above = (state >> shift) & 3
                left = (state >> (shift - 2)) & 3 if c else 0
                base = state & clear
                for color in choices:
                    if color != above and color != left:
                        new_state = base | (color << shift)
                        next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

