from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers in [1, n] expressible as a**b with a >= 1 and b >= 2."""
    if n < 1:
        return 0

    # If x > 1 has prime factorization with exponent gcd g, then x is
    # a kth power exactly when k divides g. Thus its weight in the sum
    # below is -sum(mu(k) for k | g, k >= 2), which is 1 iff g > 1.
    limit = n.bit_length() - 1
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                prime[multiple] = False
                mu[multiple] *= -1
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    def integer_root(exponent: int) -> int:
        if exponent == 2:
            return isqrt(n)
        low = 1
        high = 1 << ((n.bit_length() + exponent - 1) // exponent)
        while high - low > 1:
            middle = (low + high) // 2
            if middle ** exponent <= n:
                low = middle
            else:
                high = middle
        return low

    # Count 1 once, and exclude base 1 from each inclusion-exclusion term.
    answer = 1
    for exponent in range(2, limit + 1):
        if mu[exponent]:
            answer -= mu[exponent] * (integer_root(exponent) - 1)
    return answer

