def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k erasable, nonempty substrings.

    Equal pairs and ABC triples can be deleted in any order. Thus a
    substring is erasable exactly when its three character counts have
    equal parity. Return the number of replacements modulo 998244353.
    """
    mod = 998244353
    length = len(s)

    # An erasable interval has equal prefix states in Z_2^2, where the
    # three letters are the three nonzero elements. Distribute length+1
    # prefix states as evenly as possible to bound the number of pairs
    # from below. Every replacement satisfies a threshold below this.
    quotient, remainder = divmod(length + 1, 4)
    minimum_pairs = (
        (4 - remainder) * quotient * (quotient - 1) // 2
        + remainder * quotient * (quotient + 1) // 2
    )
    if k <= minimum_pairs:
        return pow(3, s.count('?'), mod)

    # Consecutive prefix states differ, so no state occurs more than
    # ceil((length + 1) / 2) times. Two alternating states maximize pairs.
    if k > length * length // 4:
        return 0

    # Frequencies are relative to the current prefix state, eliminating
    # the need to retain that state as another DP coordinate.
    dp = {(1, 0, 0, 0): 1}
    codes = {'A': 1, 'B': 2, 'C': 3}
    for ch in s:
        nxt = {}
        choices = (1, 2, 3) if ch == '?' else (codes[ch],)
        for (a, b, c, d), ways in dp.items():
            for code in choices:
                if code == 1:
                    state = (b + 1, a, d, c)
                elif code == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt
    return sum(ways for counts, ways in dp.items()
               if sum(x * (x - 1) // 2 for x in counts) >= k) % mod

