from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the scored 3x3 game optimally and return the winner's name.

    Takahashi moves first, claiming red cells; Aoki claims blue cells.
    Completing a row, column, or diagonal wins immediately. If the board
    fills without a line, the player with the higher claimed-cell sum wins.
    The total of all cell values is guaranteed to be odd.
    """
    values = [value for row in grid for value in row]
    lines = (7, 56, 448, 73, 146, 292, 273, 84)

    @lru_cache(maxsize=None)
    def takahashi_wins(red: int, blue: int) -> bool:
        if any(red & line == line for line in lines):
            return True
        if any(blue & line == line for line in lines):
            return False
        occupied = red | blue
        if occupied == 511:
            difference = sum(value if red & (1 << i) else -value
                             for i, value in enumerate(values))
            return difference > 0

        red_turn = red.bit_count() == blue.bit_count()
        for i in range(9):
            bit = 1 << i
            if occupied & bit:
                continue
            outcome = (takahashi_wins(red | bit, blue) if red_turn
                       else takahashi_wins(red, blue | bit))
            if outcome == red_turn:
                return outcome
        return not red_turn

    return "Takahashi" if takahashi_wins(0, 0) else "Aoki"
